CREATE VIRTUAL TABLE t1 USING fts3(english,spanish,german); WITH RECURSIVE n(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<31) INSERT INTO t1(rowid,english,spanish,german) SELECT x, trim((CASE WHEN (x & 1)<>0 THEN 'one ' ELSE '' END)||(CASE WHEN (x & 2)<>0 THEN 'two ' ELSE '' END)||(CASE WHEN (x & 4)<>0 THEN 'three ' ELSE '' END)||(CASE WHEN (x & 8)<>0 THEN 'four ' ELSE '' END)||(CASE WHEN (x & 16)<>0 THEN 'five ' ELSE '' END)), trim((CASE WHEN (x & 1)<>0 THEN 'un ' ELSE '' END)||(CASE WHEN (x & 2)<>0 THEN 'dos ' ELSE '' END)||(CASE WHEN (x & 4)<>0 THEN 'tres ' ELSE '' END)||(CASE WHEN (x & 8)<>0 THEN 'cuatro ' ELSE '' END)||(CASE WHEN (x & 16)<>0 THEN 'cinco ' ELSE '' END)), trim((CASE WHEN (x & 1)<>0 THEN 'eine ' ELSE '' END)||(CASE WHEN (x & 2)<>0 THEN 'zwei ' ELSE '' END)||(CASE WHEN (x & 4)<>0 THEN 'drei ' ELSE '' END)||(CASE WHEN (x & 8)<>0 THEN 'vier ' ELSE '' END)||(CASE WHEN (x & 16)<>0 THEN 'funf ' ELSE '' END)) FROM n; CREATE TABLE result(rid INTEGER);